import json,os
d=json.load(open('programs/task-d4079843.json'))
i1,o1=d[0]['input'],d[0]['output']

def transform(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    rem=[c for c in cnt if c!=bg]
    stripe=None; mcol=None
    for c in rem:
        cells=[(r,cc) for r in range(h) for cc in range(w) if g[r][cc]==c]
        border=[(r,cc) for r,cc in cells if cc in (0,w-1)]
        if len(border)>=4 and len(border)==len(cells):
            stripe=c
        else:
            mcol=c
    if stripe is None:
        return [r[:] for r in g]
    out=[r[:] for r in g]
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c]==mcol]
    seg={0:[],w-1:[]}
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==stripe: seg[c].append(r)
    fills=[]
    for (r,c) in marks:
        wall=None
        if g[r][0]==stripe: wall=0
        elif g[r][w-1]==stripe: wall=w-1
        if wall is None: continue
        cols=[cc for (rr,cc) in marks if rr==r]
        far=max(cols) if wall==0 else min(cols)
        rng=list(range(wall+1,far)) if wall==0 else list(range(far+1,wall))
        fills.append(('row',r,rng))
        fills.append(('end',r,far))
        oc=w-1 if wall==0 else 0
        if seg[oc] and seg[wall]:
            rw=r-min(seg[wall])
            if rw in seg[oc]:
                wrng=list(range(1,w)) if oc==0 else list(range(0,w-1))
                fills.append(('row',rw,wrng))
    for f in fills:
        if f[0]=='row':
            _,r,rng=f
            for c in rng: out[r][c]=mcol
        else:
            _,r,c=f
            out[r][c]=4
    return out

